import pandas as pd
import seaborn as sns
from sklearn.preprocessing import StandardScaler

def task_func(df1, df2):
    if not isinstance(df1, pd.DataFrame) or not isinstance(df2, pd.DataFrame):
        raise TypeError("df1 and df2 must be pandas DataFrame objects.")
    if "id" not in df1.columns or "id" not in df2.columns:
        raise ValueError("Both dataframes must contain an 'id' column.")

    overlapping = (set(df1.columns) & set(df2.columns)) - {"id"}
    merged_df = pd.merge(df1, df2, on="id", how="outer", suffixes=("_x", "_y"))

    df1_numeric_cols = [
        col for col in df1.select_dtypes(include="number").columns
        if col != "id"
    ]

    merged_numeric_cols = [
        f"{col}_x" if col in overlapping else col
        for col in df1_numeric_cols
    ]

    if merged_numeric_cols:
        scaler = StandardScaler()
        valid_cols = [
            col for col in merged_numeric_cols
            if merged_df[col].notna().any()
        ]

        if valid_cols:
            merged_df[valid_cols] = scaler.fit_transform(merged_df[valid_cols])

        scaled_for_plot = merged_df[valid_cols].copy()
        if scaled_for_plot.empty or scaled_for_plot.dropna(how="all").empty:
            pair_plot = sns.PairGrid(pd.DataFrame({"empty": []}))
        else:
            pair_plot = sns.pairplot(scaled_for_plot)
    else:
        pair_plot = sns.PairGrid(pd.DataFrame({"empty": []}))

    return merged_df, pair_plot
